/** What each endpoint is asked and answers. */
export interface Endpoints {
  "/v1/hello": { request: HelloRequest; answer: HelloAnswer }
  "/v1/turn/start": { request: TurnStartRequest; answer: Receipt }
  "/v1/turn/end": { request: TurnEndRequest; answer: Receipt }
  "/v1/mod/alive": { request: AliveRequest; answer: AliveAnswer }
  "/v1/mod/ended": { request: EndedRequest; answer: EndedAnswer }
  "/v1/mod/state": { request: StateRequest; answer: Done }
  "/v1/mod/control": { request: ControlReply; answer: Done }
  "/v1/mirror/events": { request: MirrorBatch; answer: Done }
  "/v1/tool/plan": { request: ToolPlanRequest; answer: ToolPlan }
  "/v1/tool/result": { request: ToolResultRequest; answer: ToolAnswer }
  "/v1/tool/native": { request: ToolNativeRequest; answer: ToolAnswer }
  "/v1/session/closing": { request: ClosingRequest; answer: Done }
  "/v1/status/line": { request: StatusLineRequest; answer: Done }
  "/v1/ask/open": { request: AskOpenRequest; answer: AskOpenAnswer }
  "/v1/ask/poll": { request: AskPollRequest; answer: AskPollAnswer }
  "/v1/ask/settle": { request: AskSettleRequest; answer: Done }
}

/** The protocol's bounds. */
export const bounds = {
  // protocol is the protocol's version, which every hello names: a wrapper refuses a hello of
  // another with 409, since a loaded mod keeps speaking the one it was loaded with until the
  // room restarts.
  protocol: 2,
  // maxBodyBytes is the largest request body the endpoint reads; a longer one is refused before
  // it is parsed.
  maxBodyBytes: 65536,
  // maxWaitSeconds is the longest the endpoint holds a request before it answers, since the
  // mod's fetch gives up after 30 seconds; a longer wait is a loop of polls.
  maxWaitSeconds: 20,
  // maxEndBodyBytes is the largest turn/end or tool/result body the endpoint reads, in place of
  // maxBodyBytes, counted in the UTF-8 bytes of the whole JSON body: a turn's answer and a
  // command's output can be longer than the other requests, and the mod cuts one that would
  // pass it, saying how much it left out or marking the output cut.
  maxEndBodyBytes: 1048576,
  // aliveHoldSeconds is how long the endpoint holds a mod/alive poll before it answers; the mod
  // sends the next at once.
  aliveHoldSeconds: 15,
  // maxMirrorEventBytes bounds one mirror/events event serialized: a longer delta is split, a
  // longer settle sent in parts.
  maxMirrorEventBytes: 40960,
  // maxMirrorBatchBytes bounds one mirror/events body, which so always holds at least one event
  // with its envelope, within maxBodyBytes.
  maxMirrorBatchBytes: 49152,
  // maxMirrorOutboxBytes bounds the mirror events the mod holds unsent, mirrorMarkerBytes of it
  // kept for lost markers and turn events; past it the oldest deltas go, then the oldest
  // settles, each leaving a lost marker, then the markers collapse into one resync
  // (docs/face.md).
  maxMirrorOutboxBytes: 262144,
  // mirrorMarkerBytes is the part of maxMirrorOutboxBytes kept for lost markers and turn
  // events.
  mirrorMarkerBytes: 16384,
  // maxMirrorBlockBytes bounds one text or thinking block the mod puts together for its settle,
  // cut to its head and tail past it as the face's item is.
  maxMirrorBlockBytes: 262144,
  // aliveLapseSeconds is how long the endpoint waits for the next mod/alive poll, from the last
  // one's arrival or the hello's, before the load's heartbeat lapses and what the mod proved is
  // withdrawn.
  aliveLapseSeconds: 30,
} as const

// AskKind is what a request asks: a permission for a call, or the model's own question.
export type AskKind = "permission" | "question"
export const askKindValues: readonly AskKind[] = ["permission", "question"]

// AskOpenRequest is a request to open: what the harness's question dialog shows, and for a
// permission the call it is about.
export interface AskOpenRequest {
  // loadId is the admitted load asking.
  loadId: string
  // kind is what the request asks.
  kind: AskKind
  // tool is a permission's tool, as the model names it.
  tool?: string
  // input is a permission's call arguments as JSON text, cut by the mod to what a body takes.
  input?: string
  // cwd is the directory the worker runs in.
  cwd?: string
  // readOnly says the engine's check called a permission's call read-only (Claude Code
  // 2.1.304+), absent when it did not say; the call is still main's to answer.
  readOnly?: boolean
  // questions are the dialog's questions; a permission's one question has its three choices.
  questions: AskQuestion[]
}

// AskQuestion is one question of a dialog.
export interface AskQuestion {
  // question is the question's text, which an answer is keyed by.
  question: string
  // header is the question's short label.
  header?: string
  // multiSelect says several options may be chosen.
  multiSelect?: boolean
  // options are the question's options, in order.
  options: AskOption[]
}

// AskOption is one option of a question.
export interface AskOption {
  // label is the option's label, which an answer names.
  label: string
  // description says what the option means.
  description?: string
}

// AskOpenAnswer is an opened request.
export interface AskOpenAnswer {
  // id is the request's id, which main's answer names.
  id: string
}

// AskPollRequest asks what became of an open request.
export interface AskPollRequest {
  // loadId is the admitted load asking.
  loadId: string
  // id is the request.
  id: string
}

// AskState is what became of a request: nothing yet, main's answer, settled, or past its
// deadline.
export type AskState = "pending" | "answered" | "settled" | "expired"
export const askStateValues: readonly AskState[] = ["pending", "answered", "settled", "expired"]

// AskPollAnswer is what became of a request.
export interface AskPollAnswer {
  // state is what became of the request.
  state: AskState
  // answers are main's answers, one per question, when answered.
  answers?: AskAnswer[]
  // reason is the reason main gave a refused permission.
  reason?: string
}

// AskAnswer is main's answer to one question.
export interface AskAnswer {
  // question is the question's text.
  question: string
  // answer is the label chosen, the labels chosen joined with a comma and a space, or the text
  // typed under Other.
  answer: string
}

// AskWinner is the answer a request was settled with: main's, the person's at the screen, none
// by the deadline, or none because the call was cut short.
export type AskWinner = "main" | "local" | "expired" | "aborted"
export const askWinnerValues: readonly AskWinner[] = ["main", "local", "expired", "aborted"]

// AskSettleRequest ends an open request.
export interface AskSettleRequest {
  // loadId is the admitted load settling.
  loadId: string
  // id is the request.
  id: string
  // winner is the answer that came first.
  winner: AskWinner
}

// Refusal is the answer of an endpoint that did not do what was asked, with a status other than
// 200.
export interface Refusal {
  // error says why, in words for a person.
  error: string
  // loadSeq is, on a hello refused 410 for a number below the current load's, that load's
  // number: a load whose store shows no number above its own takes the next above this one and
  // says hello once more.
  loadSeq?: number
}

// StatusLineRequest is what the status line's input tells of the session as Claude Code gave it
// — its prompt_cache, effort, model name and thinking — without transcript content.
export interface StatusLineRequest {
  // ttl is the cache's lifetime of the last request, 5m or 1h, absent when unknown.
  ttl?: string
  // expiresAt is when the cache expires, in seconds since the epoch, absent when unknown.
  expiresAt?: number
  // warm says Claude Code takes the cache for warm; absent when the input has no prompt_cache,
  // before the first request, and then no cache field is sent.
  warm?: boolean
  // effort is the input's effort.level, the session's effort setting, which follows /effort
  // before any request; absent for a model without effort.
  effort?: string
  // modelName is the input's model.display_name, the harness's own name of the session's model,
  // which follows /model; absent when the input has none.
  modelName?: string
  // thinking is the input's thinking.enabled, whether the session's thinking is on, which
  // follows its toggle; absent when the input has none.
  thinking?: boolean
}

// ClosingRequest says the harness's process has begun to end.
export interface ClosingRequest {
  // loadId is the admitted load telling.
  loadId: string
  // reason is why, in the harness's word for a session's end (prompt_input_exit for /exit,
  // ctrl+c and ctrl+d).
  reason: string
}

// MirrorBatch is the events of a session rewake's face draws, in the order the mod saw them, at
// most maxMirrorBatchBytes; one batch in flight, never sent again.
export interface MirrorBatch {
  // loadId is the load sending, the one its admitted hello named.
  loadId: string
  // generation is its heartbeat generation.
  generation: number
  // events are the events.
  events: MirrorEvent[]
}

// MirrorEvent is one thing the session showed, in the face's neutral words (docs/face.md): a
// prompt, a delta of a block then its settle in parts, a tool call's start, input and result, a
// turn's state, a lost settle or a resync standing for what the outbox dropped.
export interface MirrorEvent {
  // kind is what the event says.
  kind: MirrorEventKind
  // id names the item: a prompt's, a block's, a tool call's.
  id?: string
  // turn is the harness's turn.
  turn?: string
  // block is what a delta or a settle streams.
  block?: MirrorBlock
  // text is a delta's text, a settle's part, a prompt's text, a tool's input or its result.
  text?: string
  // origin is who typed a prompt.
  origin?: string
  // name is a tool's name.
  name?: string
  // status is how a tool call ended, or refused on a prompt of the face the engine dropped.
  status?: MirrorEnd
  // state is a turn event's state.
  state?: MirrorTurn
  // part is a settle's part, from 0.
  part?: number
  // of is how many parts the settle has.
  of?: number
  // lost counts the events a resync stands for.
  lost?: number
  // retry is how many of the working turn's requests failed in a row, on a turn event that says
  // working; the mod sends none, as Claude Code tells a mod of no retry
  // (docs/research-claude-mod.md).
  retry?: number
  // permit is how the call of a result was let run or refused, where the mod could tell.
  permit?: MirrorPermit
  // mode is the session's permission mode as Claude Code names it, on a mode event.
  mode?: string
  // level is the thinking level the face's shift+tab moves, on a level event; the mod sends
  // none, as the face moves no level of a Claude Code session (docs/face.md).
  level?: string
}

// MirrorEventKind is a mirror event's kind.
export type MirrorEventKind = "prompt" | "delta" | "settle" | "tool" | "input" | "result" | "turn" | "mode" | "lost" | "resync"
export const mirrorEventKindValues: readonly MirrorEventKind[] = ["prompt", "delta", "settle", "tool", "input", "result", "turn", "mode", "lost", "resync"]

// MirrorPermit is who let a call run or refused it, in the face's words (docs/face.md, Permit).
export interface MirrorPermit {
  // by is who settled the call.
  by: MirrorPermitBy
  // allowed says the call was let run.
  allowed: boolean
  // reason is a refusal's text as the session's screen writes it after the decider's name, a
  // link included, within a short field.
  reason?: string
}

// MirrorPermitBy is who settled a call: a settings rule, the mode or the tool's own check, auto
// mode's classifier, the person at the dialog, rewake's permission request, a hook.
export type MirrorPermitBy = "rule" | "mode" | "classifier" | "person" | "rewake" | "hook"
export const mirrorPermitByValues: readonly MirrorPermitBy[] = ["rule", "mode", "classifier", "person", "rewake", "hook"]

// MirrorBlock is a block's kind: a reply's text or thinking.
export type MirrorBlock = "text" | "thinking"
export const mirrorBlockValues: readonly MirrorBlock[] = ["text", "thinking"]

// MirrorEnd is how a tool call ended.
export type MirrorEnd = "done" | "error" | "refused"
export const mirrorEndValues: readonly MirrorEnd[] = ["done", "error", "refused"]

// MirrorTurn is the turn's state a turn event says.
export type MirrorTurn = "working" | "idle" | "compacting"
export const mirrorTurnValues: readonly MirrorTurn[] = ["working", "idle", "compacting"]

// ToolEntry is one of rewake's tools as the load registers it: the wrapper's words, sent as
// data so a change reaches a running session with the wrapper's restart.
export interface ToolEntry {
  // name is the tool's name; the model sees mcp__rewake__<name>.
  name: string
  // description is what the model reads of it.
  description: string
  // inputSchema is its input's JSON Schema.
  inputSchema: unknown
}

// ToolPlanRequest is a call of one of rewake's tools, as the model made it.
export interface ToolPlanRequest {
  // loadId is the admitted load asking.
  loadId: string
  // tool is the tool's name, without the mcp__rewake__ prefix.
  tool: string
  // arguments are the call's arguments as the model wrote them, less the keys the harness
  // carries beside them.
  arguments: unknown
}

// ToolPlan is a call's command, run by argv with no shell, its variables set over the harness's
// environment, in the session's directory; or why none runs.
export interface ToolPlan {
  // argv is the command, argv[0] the rewake the run's room runs.
  argv?: string[]
  // env are the run's variables the command answers for.
  env?: EnvVar[]
  // timeoutMs bounds the command; past it the harness stops it.
  timeoutMs?: number
  // refused is why nothing runs, the call's error result as the model reads it; absent with a
  // command.
  refused?: string
}

// EnvVar is one variable of a command's environment.
export interface EnvVar {
  // name is its name.
  name: string
  // value is its value.
  value: string
}

// ToolResultRequest is what the harness said of a planned command.
export interface ToolResultRequest {
  // loadId is the admitted load telling.
  loadId: string
  // tool is the tool's name.
  tool: string
  // ran is the harness's report.
  ran: ToolRan
}

// ToolRan is a command's end as the harness reported it, unworded.
export interface ToolRan {
  // exitCode is its exit code, absent when the harness named none.
  exitCode?: number
  // stdout is its standard output, cut by the mod to what the body takes.
  stdout: string
  // stderr is its standard error, cut by the mod to what the body takes.
  stderr: string
  // stdoutCut says the harness or the mod cut the standard output.
  stdoutCut?: boolean
  // error is why it did not run to its end, as the harness threw it: it could not start, or ran
  // past its bound.
  error?: string
}

// ToolAnswer is a call's result as the model reads it.
export interface ToolAnswer {
  // text is the result's text.
  text: string
  // isError says the call failed.
  isError: boolean
  // enterWorktree is, for worktree_enter, the checkout rewake made and claimed, which the load
  // moves the session into and then reports at tool/native; text is then what tool/native
  // carries back.
  enterWorktree?: string
}

// ToolNativeRequest is what came of moving the session into the checkout worktree_enter made.
export interface ToolNativeRequest {
  // loadId is the admitted load telling.
  loadId: string
  // tool is the tool's name.
  tool: string
  // made is the text tool/result answered with the checkout.
  made: string
  // path is the checkout.
  path: string
  // inside says the session already works in it, so no move was made.
  inside: boolean
  // moved is the harness's answer to the move, absent when none was made.
  moved?: NativeCall
}

// NativeCall is a harness call's answer, unworded.
export interface NativeCall {
  // deny is the refusal a hook or the engine answered.
  deny?: string
  // isError says the call reported an error.
  isError?: boolean
  // text is the call's text.
  text?: string
  // error is what the call threw.
  error?: string
}

// Done is the answer of an endpoint that did what was asked and has nothing to say.
export type Done = Record<string, never>

// HelloRequest is what a load of the mod says of itself.
export interface HelloRequest {
  // loadId names this load of the mod; a reload is a new load, and every later request carries
  // the id its hello gave.
  loadId: string
  // sessionId is the harness's id of the conversation the load runs in.
  sessionId: string
  // harnessVersion is the harness's version as the mod reads it.
  harnessVersion: string
  // loadSeq orders the run's loads: each load takes the next number of a counter the harness's
  // store keeps for the run, so a later load's is higher; a hello is bound only with a number
  // above the run's current load's, the same number is that load's retry, and a lower one is
  // refused 410 as superseded.
  loadSeq: number
  // protocol is the protocol the mod speaks, the bound protocol it was generated with; a hello
  // of a mod of protocol 1 has none.
  protocol: number
  // enter says the run's environment lets it enter a checkout of its own (REWAKE_WORKTREE_ENTER
  // is 1), so the wrapper lists worktree_enter; absent otherwise.
  enter?: boolean
}

// HelloAnswer is what the run is, for this load.
export interface HelloAnswer {
  // role is the run's role, as rewake's role catalogue names it.
  role: string
  // generation is the load's heartbeat generation, which every mod/alive poll of this hello
  // carries; a retried hello of a live generation gets the same one.
  generation: number
  // mirror says rewake's own face draws the session: the load sends its conversation to
  // mirror/events, in memory only (docs/face.md); absent otherwise.
  mirror?: boolean
  // tools are rewake's tools this run is offered, which the load registers, each under its
  // name.
  tools: ToolEntry[]
  // toolsDigest names the table tools is: a poll names the one the load holds, and one whose
  // table is not the run's is answered at once with the run's.
  toolsDigest: string
}

// AliveRequest is one poll of a load's heartbeat.
export interface AliveRequest {
  // loadId is the load polling, the one its admitted hello named.
  loadId: string
  // generation is the heartbeat generation the hello answered.
  generation: number
  // work is the room work the load shows at the input, empty for none: a poll whose work is not
  // the run's is answered at once, and one without it at the hold's end.
  work?: string
  // toolsDigest names the tool table the load holds: a poll whose table is not the run's is
  // answered at once with the run's.
  toolsDigest?: string
}

// EndedRequest names the other runs whose ends the harness's store keeps.
export interface EndedRequest {
  // loadId is the admitted load asking.
  loadId: string
  // epochs are up to 32 epochs of other runs, as the store's index names them.
  epochs: string[]
}

// EndedAnswer says which of the asked runs rewake proves ended: of another boot, or their
// wrapper gone with its start time.
export interface EndedAnswer {
  // ended are the epochs proven ended; one alive or that cannot be told is left out.
  ended: string[]
}

// TurnStartRequest is a turn's start of the session's own conversation; a subagent's turn is
// not sent.
export interface TurnStartRequest {
  // loadId is the load that saw the start.
  loadId: string
  // conversation is the conversation the turn runs in.
  conversation: string
  // turnId names the turn.
  turnId: string
}

// TurnEndRequest is a turn's end of the session's own conversation, sent again with the same
// end id until its receipt comes.
export interface TurnEndRequest {
  // loadId is the admitted load sending the end, which need not be the load that saw it: a
  // later load of the run sends what an earlier one stored, and the end stays its end id and
  // its content.
  loadId: string
  // conversation is the conversation the turn ran in.
  conversation: string
  // turnId names the turn.
  turnId: string
  // endId names this end once and for good: the same end sent again carries the same id and is
  // taken once.
  endId: string
  // reason is why the turn ended.
  reason: EndReason
  // answer is the turn's final text, or what the harness said of its failure; cut by the mod at
  // the last whole character that keeps the body within maxEndBodyBytes, with a line saying how
  // many characters were left out; absent when the turn gave none.
  answer?: string
}

// EndReason is why a turn ended, mapped from the harness's own reason.
export type EndReason = "answered" | "aborted" | "refused" | "failed"
export const endReasonValues: readonly EndReason[] = ["answered", "aborted", "refused", "failed"]

// Receipt says the core took a turn's start or end.
export interface Receipt {
  // turnId is the turn taken.
  turnId: string
  // endId is the end taken; absent for a start.
  endId?: string
}

// ControlCommand is one command for the current heartbeat generation.
export interface ControlCommand {
  // id identifies the request.
  id: string
  // action is compact, interrupt, prompt from rewake's own face, or trace: text the host puts
  // into the conversation's history as an interruption's actor once the interrupted turn ended.
  action: string
  // from names the requester.
  from: string
  // focus is the optional compaction focus.
  focus: string
  // conversation names the selected conversation.
  conversation: string
  // turn is the turn an interrupt stops, as the host knows it; the mod refuses with code turn
  // when it is not the one running.
  turn?: string
  // text is a prompt's text, typed as the person, or a trace's; absent for any other action.
  text?: string
}

// AliveAnswer may carry one command; the next heartbeat never waits for its completion.
export interface AliveAnswer {
  // control is the command dispatched once to this generation.
  control?: ControlCommand
  // work is the run's room work for the hint under the input (internal/core/work): its briefs
  // with their ticks and the reports it waits on, empty for none; absent where the host reads
  // none.
  work?: string
  // tools is the run's tool table, when the poll named another: the load registers a tool new
  // or of a changed schema again and describes each by it.
  tools?: ToolEntry[]
  // toolsDigest names tools, absent with it.
  toolsDigest?: string
}

// StateRequest is a complete current observation, without transcript content.
export interface StateRequest {
  // loadId names the current load.
  loadId: string
  // generation names its live heartbeat generation.
  generation: number
  // sequence orders samples within the load.
  sequence: number
  // conversation is the selected conversation.
  conversation: string
  // activity is working or idle.
  activity: string
  // turn is the main loop's running turn, absent while idle: the host names the turn an
  // interrupt stops from it and from turn/start.
  turn?: string
  // compacting says a native compaction is in progress.
  compacting: boolean
  // compactions counts completed compactions observed by this load.
  compactions: number
  // request names the latest completed compaction request, empty for native compaction.
  request: string
  // from names its requester, empty for native compaction.
  from: string
  // dialog is what the harness said of a dialog the session waits at on its screen that the mod
  // carries to nobody, absent when none; the host tells main once per dialog.
  dialog?: string
  // waiting is what a dialog the session waits at on its screen asks while the mod holds it —
  // a permission, or the model's own question — absent when none.
  waiting?: AskKind
  // native is what the session read of itself, unconverted, which the host projects into the
  // session's state (modhost/native.go): {model: $.session.model(), cwd: $.session.cwd(),
  // usage: $.session.usage(), step: {usage, effort}} with step the last main-loop step's usage
  // and the effort its request asked for; a part that could not be read is absent.
  native?: unknown
}

// ControlReply is an initial or final result for a dispatched command, as native as the mod has
// it: the host words it (modhost/control.go).
export interface ControlReply {
  // loadId names the current load.
  loadId: string
  // generation names its live heartbeat generation.
  generation: number
  // id identifies the command.
  id: string
  // outcome is requested, done, refused or failed.
  outcome: string
  // code names the local check that refused the command, absent for any other outcome.
  code?: ControlCode
  // native is the native call's result as it resolved, $.session.compact's {skip?,
  // tokensBefore?, tokensAfter?}, or {error} with the message of what it threw; absent where
  // nothing native ran.
  native?: unknown
}

// ControlCode is the local check that refused a command just before its native call, which the
// host words (control.Refusal).
export type ControlCode = "conversation" | "busy" | "turn" | "idle"
export const controlCodeValues: readonly ControlCode[] = ["conversation", "busy", "turn", "idle"]
